    ],
  });

  assert(result.ok === true);
  const totals = invoiceTotals(result.value);
  const subtotal = 10 * 9500 + 100 * 37 + 1 * 60000;
  const devHourVAT = Math.round((10 * 9500) * 21 / 100);
  const printVAT = Math.round((100 * 37) * 9 / 100);
  const workshopVAT = 0;
  const expectedVAT = devHourVAT + printVAT + workshopVAT;
  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, subtotal + expectedVAT);
});

test('invoiceTotals with complex scenario', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 50 },
    ],
  });

  assert(result.ok === true);
  const totals = invoiceTotals(result.value);
  const devHourTotal = 5 * 9500;
  const devHourDiscount = Math.round(devHourTotal * 5 / 100);
  const devHourAfterDiscount = devHourTotal - devHourDiscount;
  const devHourVAT = roundCents(devHourAfterDiscount * 21 / 100);

  const printTotal = 100 * 37;
  const printDiscount = Math.round(printTotal * 50 / 100);
  const printAfterDiscount = printTotal - printDiscount;
  const printVAT = roundCents(printAfterDiscount * 9 / 100);

  const subtotal = devHourTotal + printTotal;
  const discount = devHourDiscount + printDiscount;
  const vat = devHourVAT + printVAT;

  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - discount + vat);
});

