test('addLine and removeLine work together', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  let invoice = result.value;

  const addResult1 = addLine(invoice, { sku: 'DES-HOUR', qty: 2 });
  assert(addResult1.ok === true);
  invoice = addResult1.value;

  const addResult2 = addLine(invoice, { sku: 'COPY-HOUR', qty: 3 });
  assert(addResult2.ok === true);
  invoice = addResult2.value;

  assert.equal(invoice.lines.length, 3);

  const removeResult = removeLine(invoice, 'DES-HOUR');
  assert(removeResult.ok === true);
  invoice = removeResult.value;

  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(invoice.lines[1].sku, 'COPY-HOUR');
});

test('addLine to the same SKU multiple times accumulates qty', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  let invoice = result.value;

  let addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert(addResult.ok === true);
  invoice = addResult.value;
  assert.equal(invoice.lines[0].qty, 8);

  addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 });
  assert(addResult.ok === true);
  invoice = addResult.value;
  assert.equal(invoice.lines[0].qty, 10);
});

test('issueInvoice assigns an invoice number and changes status', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok === true);
  const invoice = result.value;
  const issueResult = issueInvoice(invoice, []);

  assert(issueResult.ok === true);
  assert.equal(issueResult.value.number, 'INV-2026-0001');
  assert.equal(issueResult.value.status, 'issued');
  assert.equal(issueResult.value.customerId, 'C-001');
  assert.equal(issueResult.value.issueDate, '2026-10-07');
});

test('issueInvoice calculates next number based on existing invoices', () => {
